"""Explain wake results and waitqueue records and initialization."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1449': ('이름표가 없어서 아무도 부르지 않은 경우와, 이름표는 있지만 그 사람이 이미 깨어 있는 경우는 다릅니다. 둘 다 새로 깨운 사람 수는 0일 수 있습니다.', '깨우기 반환값 0의 여러 원인과 조건 변경의 책임을 구별합니다.', 'task 없음 → 0, task 있음·이미 실행 가능 → 0, task 있음·깨우기 성공 → 1을 적으세요. 0만 보고 첫 번째 경우로 단정할 수 있는지 생각하세요.', ['rcuwait_wake_up은 등록된 한 작업을 깨우려는 함수입니다. 처음 반환값 ret를 0으로 준비하고 RCU 읽기 보호 구간에 들어갑니다. 이 보호는 task 포인터를 따라 접근하는 동안의 수명 규약에 쓰입니다.', '그다음 smp_mb라는 메모리 배리어를 거쳐 task를 읽습니다. 배리어는 호출자가 먼저 바꾼 조건과 이후 task 관측의 순서를 연결합니다. 함수가 조건을 직접 바꾸는 것은 아닙니다.', '읽은 task가 NULL이면 if 안으로 가지 않습니다. 반환값은 처음의 0입니다. NULL이 아니면 wake_up_process(task)를 호출하고 그 결과를 ret에 담습니다. 따라서 0이라는 결과가 나오는 길은 하나만이 아닙니다.', 'wake_up_process의 원문은 깨웠으면 1, 이미 실행 중인 작업이면 0이라고 설명합니다. 등록은 되어 있으나 작업이 이미 실행 가능한 경우에도 새로 깨운 것이 없으므로 0일 수 있습니다. 반환 0만으로 등록 포인터가 없었다고 결론 내리면 안 됩니다.', '깨우기는 작업이 다시 실행될 기회를 주는 일입니다. 반환 1도 기다리던 조건이 반드시 참이라는 증거가 아닙니다. 대기자는 반복문에서 조건을 다시 확인해야 합니다. 이 함수에는 조건을 받아 참으로 바꾸는 인자도 없습니다.', '마지막에는 RCU 읽기 보호를 끝내고 ret를 반환합니다. 올바른 호출 흐름은 조건 변경과 공개 순서를 마련한 뒤 깨우기를 시도하는 것입니다. 한 rcuwait에 한 명만 등록한다는 외부 규약도 따로 지켜야 합니다.'], [('rcuwait_wake_up의 반환값이 0이면 task가 반드시 NULL이었을까요?', ['네. 등록된 작업이 없었다는 뜻만 있어요', '아니요. 등록된 작업이 이미 실행 가능한 경우도 있어요'], 'task가 있으면 wake_up_process의 결과를 전달합니다. 그 함수도 이미 실행 중인 경우 0을 돌려줄 수 있으므로 반환값 하나로 포인터의 존재를 확정할 수 없습니다.'), ('rcuwait_wake_up이 기다리는 조건을 직접 참으로 바꿀까요?', ['아니요. 등록된 작업을 깨우려고 시도해요', '네. 호출만 하면 어떤 조건이든 참이 돼요'], '조건 변경은 호출자가 담당하고 이 함수는 task를 확인해 깨웁니다. 깨우기와 조건 변경은 다른 일이므로 기다리는 쪽도 조건을 다시 검사합니다.')]), 'os1450': ('대기실에는 각 사람의 접수 카드와 카드들을 모아 둔 명단이 있습니다. 카드에 누구인지, 어떻게 부를지, 앞뒤 카드가 어디인지 적어 두면 여러 사람을 관리할 수 있습니다.', '대기 항목과 대기열 전체의 구조를 나누어 이해합니다.', '카드 A와 B에 flags·private·func·entry 네 칸을 그리세요. 바깥에는 head와 lock을 가진 대기열을 그려 연결하세요.', ['wait_queue_entry는 대기 항목 하나입니다. flags는 특별한 처리 방법을 나타내는 표시들을 담습니다. 예를 들어 깨우기 한도 계산에 참여하는 항목인지 같은 정보를 표시할 수 있습니다. 표시가 task의 실행 상태 자체와 같은 것은 아닙니다.', 'private는 콜백에 전달할 관련 자료의 주소입니다. 원문 타입은 void *로, 어느 종류를 가리키는지 이 선언 하나만으로 정하지 않습니다. 기본 깨우기 함수는 이것을 task 주소로 쓰지만 다른 콜백은 자기 약속에 따라 다른 문맥을 담을 수 있습니다.', 'func는 함수를 가리키는 포인터입니다. 콜백은 나중에 다른 코드가 불러 주도록 맡긴 함수입니다. 깨우는 쪽이 이 항목을 처리할 때 func가 지정한 함수를 호출합니다. 작업 번호를 담는 정수와는 다릅니다.', 'entry는 앞뒤 항목을 연결하는 이중 연결 리스트의 연결 부분입니다. 각 카드가 앞과 뒤를 가리키는 주소를 가지므로 목록에서 항목을 따라가거나 연결을 바꿀 수 있습니다. 실제 사람인 태스크와 접수 카드인 대기 항목을 구별하세요.', 'wait_queue_head는 대기열 전체를 관리합니다. head는 목록의 기준점이고 lock은 여러 실행이 동시에 목록을 바꾸지 못하도록 보호하는 잠금입니다. 접수 카드 한 장의 entry와 명단 전체의 head는 역할이 다릅니다.', '기본 콜백을 쓰려면 private에 그 콜백이 기대하는 task 주소를 넣어야 합니다. void *라고 아무 주소를 넣어도 안전하다는 뜻은 아닙니다. 사용자 콜백을 정한다면 private의 해석, 반환값 의미, 항목을 넣고 빼는 책임을 함께 맞춰야 합니다.'], [('대기 항목의 func는 무엇을 담을까요?', ['항상 작업 번호라는 정수를 담아요', '깨우기 요청을 처리할 함수의 포인터를 담아요'], 'func의 타입은 wait_queue_func_t로 함수 포인터입니다. 나중에 어떤 함수를 호출할지 정하는 자리이며 단순한 태스크 번호가 아닙니다.'), ('private의 선언이 항상 task 포인터만 담도록 강제할까요?', ['아니요. void *이며 사용하는 콜백의 약속에 따라 해석해요', '네. 선언 자체가 struct task_struct *예요'], '원문은 void *private입니다. 기본 콜백이 task로 사용한다는 약속과 구조체의 선언 타입을 구별해야 합니다. 그렇다고 콜백이 기대하지 않는 임의 주소를 넣어도 된다는 뜻은 아닙니다.')]), 'os1451': ('접수 카드에 이름과 담당자를 적었다고 앞뒤 연결까지 준비된 것은 아닙니다. 같은 “준비”라는 이름도 어느 칸을 채우는지 확인해야 합니다.', '대기 항목 초기화 함수마다 리스트 연결 상태가 다른 이유를 배웁니다.', 'DECLARE_WAITQUEUE: 링크 NULL·NULL, DEFINE_WAIT_FUNC: 링크 자기 자신·자기 자신, init_waitqueue_entry: 링크는 건드리지 않음을 세 줄로 쓰세요.', ['DECLARE_WAITQUEUE는 지정한 task를 private에 넣고 default_wake_function을 콜백으로 정합니다. entry의 두 연결 주소는 NULL로 둡니다. 이 선언은 곧바로 대기열에 등록하거나 잠드는 명령은 아닙니다.', 'DEFINE_WAIT_FUNC는 private에 current를 넣고, 인자로 받은 함수를 func에 넣습니다. entry는 LIST_HEAD_INIT으로 자기 자신을 가리키게 합니다. current는 이 선언을 실행하는 현재 작업을 뜻합니다.', '자기 참조 연결은 비어 있는 원형 리스트의 표현입니다. “다음이 나 자신”이면 아직 다른 항목이 연결되지 않았다는 뜻입니다. 두 링크가 NULL인 상태와 같은 비트 모양도 아니고, 같은 검사에 항상 쓸 수 있는 상태도 아닙니다.', 'init_waitqueue_entry는 실행 중 flags=0, private=p, func=default_wake_function만 설정합니다. 함수 안에는 INIT_LIST_HEAD가 없습니다. 따라서 이 함수만 호출했다고 아직 준비하지 않은 entry 링크를 읽어도 된다고 가정하면 안 됩니다.', 'init_wait는 current와 autoremove_wake_function을 설정하고 INIT_LIST_HEAD와 flags=0까지 수행합니다. autoremove는 깨우기 처리 중 항목 제거를 하는 콜백 계열의 이름입니다. 이름이 비슷한 init_waitqueue_entry와 실제 설정 항목이 다릅니다.', 'prepare 계열 중 list_empty로 등록 여부를 확인하는 경로는 자기 참조로 준비한 항목을 기대합니다. 반면 직접 등록하는 경로는 다른 초기화 방식과 함께 쓰일 수 있습니다. 한 방식이 무조건 잘못이라는 뜻이 아니라, 뒤에서 사용할 등록·검사 함수와 준비 방식을 맞춰야 한다는 뜻입니다.'], [('init_waitqueue_entry가 entry 링크도 자기 자신으로 초기화할까요?', ['네. 항상 모든 링크를 초기화해요', '아니요. flags, private, func만 설정해요'], '함수 본문에는 세 항목의 대입만 있고 INIT_LIST_HEAD는 없습니다. 이름에 init가 있다는 이유로 모든 필드가 준비됐다고 추측하면 안 됩니다.'), ('DECLARE_WAITQUEUE와 DEFINE_WAIT_FUNC의 초기 링크는 같을까요?', ['아니요. 앞은 NULL 링크, 뒤는 자기 참조 링크예요', '네. 둘 다 NULL 링크예요'], '각 매크로는 각각 {NULL,NULL}과 LIST_HEAD_INIT을 사용합니다. 뒤에 리스트 상태를 검사하는 함수의 기대와 연결해서 선택해야 합니다.')]), 'os1452': ('빈 대기 명단도 시작점을 알아야 합니다. 시작점이 자기 자신으로 돌아오게 연결해 두면 “아직 아무 카드도 없다”는 상태를 표현할 수 있습니다.', '대기열 전체의 잠금·검사 정보·빈 목록을 준비하는 과정을 배웁니다.', '빈 head: next=head, prev=head를 그리세요. A를 붙인 명단을 다시 빈 head로 덮으면 A를 자동으로 옮겨 주는지 생각해 보세요.', ['__init_waitqueue_head는 새 대기열 전체를 준비하는 함수입니다. 먼저 spin_lock_init로 lock을 초기화합니다. 잠금을 지금 획득하는 것과, 앞으로 쓸 수 있게 초기 상태로 준비하는 것은 다릅니다.', '그다음 lockdep_set_class_and_name으로 잠금 검사 도구에 분류 키와 이름을 연결합니다. lockdep는 잠금 사용 관계의 문제를 찾는 도구입니다. 이 검사 정보가 실제 목록을 보호하는 잠금 동작을 대신하지는 않습니다.', '헤더의 init_waitqueue_head 매크로는 호출 지점의 정적 lock_class_key를 전달합니다. 키는 검사 도구가 잠금 종류를 구별하는 데 쓰는 정보입니다. 매번 대기자를 세는 카운터나 독점권을 주는 번호가 아닙니다.', '마지막 INIT_LIST_HEAD는 head의 다음과 이전 연결을 모두 head 자신으로 설정합니다. head는 첫 대기자가 아니라 목록의 기준점입니다. 빈 명단도 유효한 기준점을 유지하므로 NULL을 따라가야만 끝을 아는 구조가 아닙니다.', 'DECLARE_WAIT_QUEUE_HEAD는 선언 때 잠금과 목록의 초기값을 제공합니다. 스택용 ONSTACK 선언은 CONFIG_LOCKDEP가 켜졌을 때 실행 중 초기화 경로를 사용합니다. 스택은 함수 호출 동안 쓰는 임시 공간이므로 다른 작업이 계속 접근하는 대기열을 남기고 함수가 끝나서는 안 됩니다.', '이미 A와 B가 연결된 head를 다시 초기화하면 기존 항목들을 옮겨 주지 않습니다. head의 연결을 자기 자신으로 덮어 기존 명단을 잃을 수 있습니다. 초기화는 새 객체를 공개하기 전에 하고, 사용 중 목록의 정리는 정해진 제거·수명 규칙으로 해야 합니다.'], [('초기화한 빈 대기열의 head 연결은 어디를 가리킬까요?', ['반드시 NULL이어야 해요', 'head 자기 자신을 가리켜요'], 'INIT_LIST_HEAD는 앞뒤 연결을 모두 자기 자신으로 설정합니다. 이 원형 리스트의 빈 상태 표현은 NULL 링크와 다릅니다.'), ('사용 중인 head를 다시 초기화하면 대기자들이 자동으로 보존될까요?', ['아니요. 기존 연결을 잃을 수 있어요', '네. 함수가 모두 새 명단으로 옮겨 줘요'], '초기화 함수에는 기존 항목을 찾아 옮기는 반복문이 없습니다. 새 빈 상태로 연결을 덮으므로 사용 중인 목록의 안전한 정리나 이전을 대신하지 않습니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_358.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
